def solve(I,O):
    I=np.array(I);O=np.array(O);H,W=I.shape
    cc=Counter(I.ravel().tolist())
    maj=cc.most_common(1)[0][0]
    others=[k for k in cc if k!=maj]
    # blocker = the color that appears rarely / acts as bar; try both assignments of roles
    best=None
    for blocker in others:
