            if filly==blocker: continue
            # pick orientation with more clean lines
            def clean_lines(color, vert):
                n=0
                if vert:
                    for c in range(W):
                        if color not in set(I[:,c].tolist()): n+=1
                else:
                    for r in range(H):
                        if color not in set(I[r,:].tolist()): n+=1
                return n
            nv,nc=clean_lines(blocker,True),clean_lines(blocker,False)
            out=I.copy()
            if nv>=nc:
                for c in range(W):
                    if blocker not in set(I[:,c].tolist()): out[:,c]=np.where(out[:,c]==maj,filly,out[:,c])
            else:
                for r in range(H):
                    if blocker not in set(I[r,:].tolist()): out[r,:]=np.where(out[r,:]==maj,filly,out[r,:])
            m=len(np.argwhere(out!=O))
            if best is None or m<best[0]: best=(m,blocker,filly,nv,nc)
    return best
